            if nm=='Write':
                seq.append(('WRITE', inp.get('file_path',''), inp.get('content','')))
            elif nm=='Grep':
                seq.append(('GREP', inp.get('pattern',''), inp.get('path','')))
            elif nm=='Read':
                seq.append(('READ', inp.get('file_path',''), str(inp.get('offset','')), str(inp.get('limit',''))))
            else:
                seq.append((nm.upper(), json.dumps(inp)[:80]))
